package config

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"strings"
)

const appDirName = "gotify-desktop"

// Config holds persistent application settings. Passwords are never stored.
type Config struct {
	ServerURL    string `json:"server_url"`
	ClientToken  string `json:"client_token"`
	MinPriority  int    `json:"min_priority"`
	LastMessageID uint  `json:"last_message_id,omitempty"`
}

func Default() Config {
	return Config{MinPriority: 0}
}

// Dir returns the platform config directory for this app.
func Dir() (string, error) {
	base, err := os.UserConfigDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(base, appDirName), nil
}

// Path returns the full path to config.json.
func Path() (string, error) {
	dir, err := Dir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, "config.json"), nil
}

// Load reads config from disk. Missing file returns Default() with nil error.
func Load() (Config, error) {
	path, err := Path()
	if err != nil {
		return Default(), err
	}
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return Default(), nil
	}
	if err != nil {
		return Default(), err
	}
	cfg := Default()
	if err := json.Unmarshal(data, &cfg); err != nil {
		return Default(), fmt.Errorf("parse config: %w", err)
	}
	return cfg, nil
}

// Save writes config atomically.
func Save(cfg Config) error {
	dir, err := Dir()
	if err != nil {
		return err
	}
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	path, err := Path()
	if err != nil {
		return err
	}
	data, err := json.MarshalIndent(cfg, "", "  ")
	if err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o600); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

// Configured reports whether server URL and client token are present.
func (c Config) Configured() bool {
	return strings.TrimSpace(c.ServerURL) != "" && strings.TrimSpace(c.ClientToken) != ""
}

// NormalizeServerURL trims trailing slashes and validates http(s) scheme.
func NormalizeServerURL(raw string) (string, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return "", errors.New("server URL is required")
	}
	if !strings.Contains(raw, "://") {
		raw = "https://" + raw
	}
	u, err := url.Parse(raw)
	if err != nil {
		return "", fmt.Errorf("invalid server URL: %w", err)
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return "", fmt.Errorf("unsupported URL scheme %q (use http or https)", u.Scheme)
	}
	if u.Host == "" {
		return "", errors.New("server URL must include a host")
	}
	u.Path = strings.TrimRight(u.Path, "/")
	u.RawQuery = ""
	u.Fragment = ""
	return u.String(), nil
}

// StreamURL builds the Gotify websocket stream URL from a server base URL.
func StreamURL(serverURL, token string) (string, error) {
	base, err := url.Parse(serverURL)
	if err != nil {
		return "", err
	}
	switch base.Scheme {
	case "https":
		base.Scheme = "wss"
	case "http":
		base.Scheme = "ws"
	default:
		return "", fmt.Errorf("unsupported scheme %q", base.Scheme)
	}
	base.Path = strings.TrimRight(base.Path, "/") + "/stream"
	q := base.Query()
	q.Set("token", token)
	base.RawQuery = q.Encode()
	return base.String(), nil
}

// ShouldNotify returns true if message priority meets the configured minimum.
func ShouldNotify(minPriority, messagePriority int) bool {
	return messagePriority >= minPriority
}

package config

import (
	"os"
	"path/filepath"
	"testing"
)

func TestNormalizeServerURL(t *testing.T) {
	tests := []struct {
		in      string
		want    string
		wantErr bool
	}{
		{"https://gotify.example.com", "https://gotify.example.com", false},
		{"https://gotify.example.com/", "https://gotify.example.com", false},
		{"http://localhost:8080/", "http://localhost:8080", false},
		{"gotify.example.com", "https://gotify.example.com", false},
		{"", "", true},
		{"ftp://x", "", true},
	}
	for _, tc := range tests {
		got, err := NormalizeServerURL(tc.in)
		if tc.wantErr {
			if err == nil {
				t.Fatalf("NormalizeServerURL(%q) expected error", tc.in)
			}
			continue
		}
		if err != nil {
			t.Fatalf("NormalizeServerURL(%q): %v", tc.in, err)
		}
		if got != tc.want {
			t.Fatalf("NormalizeServerURL(%q)=%q want %q", tc.in, got, tc.want)
		}
	}
}

func TestStreamURL(t *testing.T) {
	got, err := StreamURL("https://gotify.example.com", "tok")
	if err != nil {
		t.Fatal(err)
	}
	want := "wss://gotify.example.com/stream?token=tok"
	if got != want {
		t.Fatalf("got %q want %q", got, want)
	}

	got, err = StreamURL("http://localhost:80", "abc")
	if err != nil {
		t.Fatal(err)
	}
	want = "ws://localhost:80/stream?token=abc"
	if got != want {
		t.Fatalf("got %q want %q", got, want)
	}
}

func TestShouldNotify(t *testing.T) {
	if !ShouldNotify(0, 0) {
		t.Fatal("priority 0 should notify when min is 0")
	}
	if ShouldNotify(5, 4) {
		t.Fatal("priority 4 should not notify when min is 5")
	}
	if !ShouldNotify(5, 5) {
		t.Fatal("priority 5 should notify when min is 5")
	}
}

func TestSaveLoad(t *testing.T) {
	tmp := t.TempDir()
	t.Setenv("XDG_CONFIG_HOME", tmp)
	// UserConfigDir on Linux uses XDG_CONFIG_HOME; on other platforms may differ.
	// Force path by overriding via writing through Dir after setting home-like env.
	if dir, err := Dir(); err == nil {
		_ = os.MkdirAll(dir, 0o700)
	}

	cfg := Config{
		ServerURL:   "https://gotify.example.com",
		ClientToken: "secret",
		MinPriority: 2,
	}
	// Save via direct path if UserConfigDir doesn't respect XDG in this env
	path := filepath.Join(tmp, appDirName, "config.json")
	if d, err := Dir(); err == nil {
		path = filepath.Join(d, "config.json")
	}
	_ = os.MkdirAll(filepath.Dir(path), 0o700)

	if err := Save(cfg); err != nil {
		t.Fatal(err)
	}
	loaded, err := Load()
	if err != nil {
		t.Fatal(err)
	}
	if !loaded.Configured() {
		t.Fatal("expected configured")
	}
	if loaded.ServerURL != cfg.ServerURL || loaded.ClientToken != cfg.ClientToken || loaded.MinPriority != cfg.MinPriority {
		t.Fatalf("loaded %+v want %+v", loaded, cfg)
	}
}

package auth

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"time"
)

// Client talks to the Gotify HTTP API using Basic Auth (setup) or client token.
type Client struct {
	HTTP *http.Client
}

func New() *Client {
	return &Client{
		HTTP: &http.Client{Timeout: 15 * time.Second},
	}
}

type userInfo struct {
	ID   uint   `json:"id"`
	Name string `json:"name"`
}

type clientResponse struct {
	ID    uint   `json:"id"`
	Name  string `json:"name"`
	Token string `json:"token"`
}

// VerifyAndCreateClient checks credentials and creates a desktop client token.
// The password is only used for this request and is not retained by this package.
func (c *Client) VerifyAndCreateClient(serverURL, username, password string) (token string, err error) {
	serverURL = strings.TrimRight(strings.TrimSpace(serverURL), "/")
	if serverURL == "" || username == "" || password == "" {
		return "", fmt.Errorf("server URL, username and password are required")
	}

	if err := c.verifyUser(serverURL, username, password); err != nil {
		return "", err
	}

	name := clientName()
	token, err = c.createClient(serverURL, username, password, name)
	if err != nil {
		return "", err
	}
	return token, nil
}

func (c *Client) verifyUser(serverURL, username, password string) error {
	req, err := http.NewRequest(http.MethodGet, serverURL+"/current/user", nil)
	if err != nil {
		return err
	}
	req.SetBasicAuth(username, password)
	req.Header.Set("Accept", "application/json")

	resp, err := c.HTTP.Do(req)
	if err != nil {
		return fmt.Errorf("cannot reach Gotify server: %w", err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))

	switch resp.StatusCode {
	case http.StatusOK:
		var u userInfo
		if err := json.Unmarshal(body, &u); err != nil {
			return fmt.Errorf("unexpected user response: %w", err)
		}
		return nil
	case http.StatusUnauthorized, http.StatusForbidden:
		return fmt.Errorf("invalid username or password")
	default:
		return fmt.Errorf("gotify returned %s: %s", resp.Status, truncate(string(body), 200))
	}
}

func (c *Client) createClient(serverURL, username, password, name string) (string, error) {
	payload, err := json.Marshal(map[string]string{"name": name})
	if err != nil {
		return "", err
	}
	req, err := http.NewRequest(http.MethodPost, serverURL+"/client", bytes.NewReader(payload))
	if err != nil {
		return "", err
	}
	req.SetBasicAuth(username, password)
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Accept", "application/json")

	resp, err := c.HTTP.Do(req)
	if err != nil {
		return "", fmt.Errorf("create client failed: %w", err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("create client returned %s: %s", resp.Status, truncate(string(body), 200))
	}

	var cr clientResponse
	if err := json.Unmarshal(body, &cr); err != nil {
		return "", fmt.Errorf("parse client response: %w", err)
	}
	if cr.Token == "" {
		return "", fmt.Errorf("gotify did not return a client token")
	}
	return cr.Token, nil
}

func clientName() string {
	host, err := os.Hostname()
	if err != nil || host == "" {
		host = "desktop"
	}
	return "gotify-desktop-" + host
}

func truncate(s string, n int) string {
	s = strings.TrimSpace(s)
	if len(s) <= n {
		return s
	}
	return s[:n] + "…"
}

package stream

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

// Message is a Gotify stream message.
type Message struct {
	ID       uint   `json:"id"`
	AppID    uint   `json:"appid"`
	Message  string `json:"message"`
	Title    string `json:"title"`
	Priority int    `json:"priority"`
	Date     string `json:"date"`
}

// Handler is called for each received message.
type Handler func(msg Message)

// StatusHandler reports connection state changes.
type StatusHandler func(connected bool, errMsg string)

// Client maintains a reconnecting websocket to Gotify /stream.
type Client struct {
	URL     string
	OnMessage Handler
	OnStatus  StatusHandler

	mu     sync.Mutex
	cancel context.CancelFunc
	conn   *websocket.Conn
}

// Start begins the reconnect loop. Safe to call once; call Stop to end.
func (c *Client) Start() {
	c.mu.Lock()
	if c.cancel != nil {
		c.mu.Unlock()
		return
	}
	ctx, cancel := context.WithCancel(context.Background())
	c.cancel = cancel
	c.mu.Unlock()
	go c.loop(ctx)
}

// Stop closes the connection and stops reconnecting.
func (c *Client) Stop() {
	c.mu.Lock()
	cancel := c.cancel
	c.cancel = nil
	conn := c.conn
	c.conn = nil
	c.mu.Unlock()
	if cancel != nil {
		cancel()
	}
	if conn != nil {
		_ = conn.Close()
	}
	c.emitStatus(false, "")
}

func (c *Client) loop(ctx context.Context) {
	backoff := time.Second
	const maxBackoff = 30 * time.Second

	for {
		if ctx.Err() != nil {
			return
		}
		err := c.connectOnce(ctx)
		if ctx.Err() != nil {
			return
		}
		msg := ""
		if err != nil {
			msg = err.Error()
		}
		c.emitStatus(false, msg)
		select {
		case <-ctx.Done():
			return
		case <-time.After(backoff):
		}
		backoff *= 2
		if backoff > maxBackoff {
			backoff = maxBackoff
		}
	}
}

func (c *Client) connectOnce(ctx context.Context) error {
	dialer := websocket.Dialer{
		HandshakeTimeout: 15 * time.Second,
		Proxy:            http.ProxyFromEnvironment,
	}
	conn, resp, err := dialer.DialContext(ctx, c.URL, nil)
	if resp != nil && resp.Body != nil {
		_ = resp.Body.Close()
	}
	if err != nil {
		if resp != nil && resp.StatusCode == http.StatusUnauthorized {
			return fmt.Errorf("unauthorized: invalid client token")
		}
		return fmt.Errorf("websocket dial: %w", err)
	}

	c.mu.Lock()
	c.conn = conn
	c.mu.Unlock()
	c.emitStatus(true, "")
	defer func() {
		c.mu.Lock()
		if c.conn == conn {
			c.conn = nil
		}
		c.mu.Unlock()
		_ = conn.Close()
	}()

	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
		}
		_ = conn.SetReadDeadline(time.Now().Add(90 * time.Second))
		_, data, err := conn.ReadMessage()
		if err != nil {
			return err
		}
		var msg Message
		if err := json.Unmarshal(data, &msg); err != nil {
			continue
		}
		if c.OnMessage != nil {
			c.OnMessage(msg)
		}
	}
}

func (c *Client) emitStatus(connected bool, errMsg string) {
	if c.OnStatus != nil {
		c.OnStatus(connected, errMsg)
	}
}

package notify

import (
	"context"
	"fmt"
	"sync"

	"github.com/wailsapp/wails/v2/pkg/runtime"
)

// Notifier wraps Wails native notifications.
type Notifier struct {
	mu      sync.Mutex
	ctx     context.Context
	ready   bool
	initErr error
}

// Init initializes the platform notification system. Call from OnStartup.
func (n *Notifier) Init(ctx context.Context) error {
	n.mu.Lock()
	defer n.mu.Unlock()
	n.ctx = ctx
	if err := runtime.InitializeNotifications(ctx); err != nil {
		n.initErr = err
		n.ready = false
		return err
	}
	if !runtime.IsNotificationAvailable(ctx) {
		n.initErr = fmt.Errorf("notifications not available on this platform")
		n.ready = false
		return n.initErr
	}
	authorized, err := runtime.CheckNotificationAuthorization(ctx)
	if err == nil && !authorized {
		authorized, err = runtime.RequestNotificationAuthorization(ctx)
		if err != nil || !authorized {
			n.initErr = fmt.Errorf("notification permission denied")
			n.ready = false
			return n.initErr
		}
	}
	n.ready = true
	n.initErr = nil
	return nil
}

// Ready reports whether notifications can be sent.
func (n *Notifier) Ready() bool {
	n.mu.Lock()
	defer n.mu.Unlock()
	return n.ready
}

// Show displays a desktop notification.
func (n *Notifier) Show(id, title, body string) error {
	n.mu.Lock()
	ctx := n.ctx
	ready := n.ready
	n.mu.Unlock()
	if !ready || ctx == nil {
		return fmt.Errorf("notifications not initialized")
	}
	if title == "" {
		title = "Gotify"
	}
	return runtime.SendNotification(ctx, runtime.NotificationOptions{
		ID:    id,
		Title: title,
		Body:  body,
	})
}

package tray

import (
	"sync"

	"fyne.io/systray"
)

// Callbacks wired by the application.
type Callbacks struct {
	OnOpen     func()
	OnSettings func()
	OnQuit     func()
}

// Controller manages the system tray icon and menu.
type Controller struct {
	icon []byte
	cb   Callbacks

	mu          sync.Mutex
	statusItem  *systray.MenuItem
	started     bool
}

// New creates a tray controller. icon should be PNG bytes (Linux/macOS) or ICO (Windows).
func New(icon []byte, cb Callbacks) *Controller {
	return &Controller{icon: icon, cb: cb}
}

// Start runs the systray event loop in a background goroutine.
func (c *Controller) Start() {
	c.mu.Lock()
	if c.started {
		c.mu.Unlock()
		return
	}
	c.started = true
	c.mu.Unlock()
	go systray.Run(c.onReady, c.onExit)
}

// Stop quits the systray loop.
func (c *Controller) Stop() {
	systray.Quit()
}

// SetStatus updates the status menu label.
func (c *Controller) SetStatus(text string) {
	c.mu.Lock()
	item := c.statusItem
	c.mu.Unlock()
	if item != nil {
		item.SetTitle(text)
	}
}

func (c *Controller) onReady() {
	systray.SetTitle("Gotify")
	systray.SetTooltip("Gotify Desktop")
	if len(c.icon) > 0 {
		systray.SetIcon(c.icon)
	}

	status := systray.AddMenuItem("Status: starting…", "Connection status")
	status.Disable()
	c.mu.Lock()
	c.statusItem = status
	c.mu.Unlock()

	systray.AddSeparator()
	open := systray.AddMenuItem("Open window", "Show the Gotify window")
	settings := systray.AddMenuItem("Settings", "Open connection settings")
	systray.AddSeparator()
	quit := systray.AddMenuItem("Quit", "Exit Gotify Desktop")

	go func() {
		for {
			select {
			case <-open.ClickedCh:
				if c.cb.OnOpen != nil {
					c.cb.OnOpen()
				}
			case <-settings.ClickedCh:
				if c.cb.OnSettings != nil {
					c.cb.OnSettings()
				}
			case <-quit.ClickedCh:
				if c.cb.OnQuit != nil {
					c.cb.OnQuit()
				}
				systray.Quit()
				return
			}
		}
	}()
}

func (c *Controller) onExit() {}

package main

import (
	"context"
	"fmt"
	"strconv"
	"sync"

	"github.com/elpatron68/gotify-desktop/internal/auth"
	"github.com/elpatron68/gotify-desktop/internal/config"
	"github.com/elpatron68/gotify-desktop/internal/notify"
	"github.com/elpatron68/gotify-desktop/internal/stream"
	"github.com/elpatron68/gotify-desktop/internal/tray"
	"github.com/wailsapp/wails/v2/pkg/runtime"
)

// AppStatus is exposed to the frontend.
type AppStatus struct {
	Configured bool   `json:"configured"`
	Connected  bool   `json:"connected"`
	ServerURL  string `json:"serverUrl"`
	View       string `json:"view"` // "setup" | "gotify"
	Error      string `json:"error"`
	MinPriority int   `json:"minPriority"`
}

// App is the Wails-bound application core.
type App struct {
	ctx context.Context

	mu        sync.Mutex
	cfg       config.Config
	view      string
	connected bool
	lastErr   string
	quitting  bool

	auth    *auth.Client
	stream  *stream.Client
	notify  *notify.Notifier
	tray    *tray.Controller
	trayIcon []byte
}

// NewApp creates the application.
func NewApp(trayIcon []byte) *App {
	return &App{
		auth:     auth.New(),
		notify:   &notify.Notifier{},
		view:     "setup",
		trayIcon: trayIcon,
	}
}

func (a *App) startup(ctx context.Context) {
	a.ctx = ctx
	_ = a.notify.Init(ctx)

	cfg, err := config.Load()
	if err != nil {
		a.setError(err.Error())
	} else {
		a.mu.Lock()
		a.cfg = cfg
		a.mu.Unlock()
	}

	a.tray = tray.New(a.trayIcon, tray.Callbacks{
		OnOpen:     a.ShowWindow,
		OnSettings: a.OpenSettings,
		OnQuit:     a.Quit,
	})
	a.tray.Start()

	if a.cfg.Configured() {
		a.mu.Lock()
		a.view = "gotify"
		a.mu.Unlock()
		a.startStream()
	} else {
		a.tray.SetStatus("Status: not configured")
	}
	a.emitStatus()
}

func (a *App) shutdown(ctx context.Context) {
	a.stopStream()
	if a.tray != nil {
		a.tray.Stop()
	}
}

func (a *App) beforeClose(ctx context.Context) (prevent bool) {
	a.mu.Lock()
	quitting := a.quitting
	a.mu.Unlock()
	if quitting {
		return false
	}
	runtime.WindowHide(ctx)
	return true
}

// GetStatus returns the current app status for the UI.
func (a *App) GetStatus() AppStatus {
	a.mu.Lock()
	defer a.mu.Unlock()
	return AppStatus{
		Configured:  a.cfg.Configured(),
		Connected:   a.connected,
		ServerURL:   a.cfg.ServerURL,
		View:        a.view,
		Error:       a.lastErr,
		MinPriority: a.cfg.MinPriority,
	}
}

// GetServerURL returns the configured Gotify base URL.
func (a *App) GetServerURL() string {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.cfg.ServerURL
}

// IsConfigured reports whether a client token exists.
func (a *App) IsConfigured() bool {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.cfg.Configured()
}

// Connect authenticates with username/password, creates a client token, and starts the stream.
func (a *App) Connect(serverURL, username, password string) error {
	normalized, err := config.NormalizeServerURL(serverURL)
	if err != nil {
		return err
	}
	token, err := a.auth.VerifyAndCreateClient(normalized, username, password)
	if err != nil {
		return err
	}

	a.mu.Lock()
	a.cfg.ServerURL = normalized
	a.cfg.ClientToken = REDACTED
	a.view = "gotify"
	a.lastErr = ""
	cfg := a.cfg
	a.mu.Unlock()

	if err := config.Save(cfg); err != nil {
		return fmt.Errorf("save config: %w", err)
	}

	a.stopStream()
	a.startStream()
	a.emitStatus()
	runtime.EventsEmit(a.ctx, "show-gotify", normalized)
	return nil
}

// OpenSettings switches the UI back to the setup view.
func (a *App) OpenSettings() {
	a.mu.Lock()
	a.view = "setup"
	a.mu.Unlock()
	a.ShowWindow()
	a.emitStatus()
	runtime.EventsEmit(a.ctx, "show-setup")
}

// ShowWindow brings the main window to the front.
func (a *App) ShowWindow() {
	if a.ctx == nil {
		return
	}
	runtime.WindowShow(a.ctx)
	runtime.WindowUnminimise(a.ctx)
}

// Quit exits the application for real.
func (a *App) Quit() {
	a.mu.Lock()
	a.quitting = true
	a.mu.Unlock()
	a.stopStream()
	if a.ctx != nil {
		runtime.Quit(a.ctx)
	}
}

func (a *App) startStream() {
	a.mu.Lock()
	cfg := a.cfg
	a.mu.Unlock()
	if !cfg.Configured() {
		return
	}
	wsURL, err := config.StreamURL(cfg.ServerURL, cfg.ClientToken)
	if err != nil {
		a.setError(err.Error())
		a.emitStatus()
		return
	}

	client := &stream.Client{
		URL: wsURL,
		OnMessage: func(msg stream.Message) {
			a.handleMessage(msg)
		},
		OnStatus: func(connected bool, errMsg string) {
			a.mu.Lock()
			a.connected = connected
			if errMsg != "" {
				a.lastErr = errMsg
			} else if connected {
				a.lastErr = ""
			}
			a.mu.Unlock()
			if a.tray != nil {
				if connected {
					a.tray.SetStatus("Status: connected")
				} else if errMsg != "" {
					a.tray.SetStatus("Status: error")
				} else {
					a.tray.SetStatus("Status: disconnected")
				}
			}
			a.emitStatus()
			if errMsg != "" && containsUnauthorized(errMsg) {
				a.OpenSettings()
			}
		},
	}
	a.mu.Lock()
	a.stream = client
	a.mu.Unlock()
	client.Start()
}

func (a *App) stopStream() {
	a.mu.Lock()
	s := a.stream
	a.stream = nil
	a.connected = false
	a.mu.Unlock()
	if s != nil {
		s.Stop()
	}
}

func (a *App) handleMessage(msg stream.Message) {
	a.mu.Lock()
	minP := a.cfg.MinPriority
	lastID := a.cfg.LastMessageID
	a.mu.Unlock()

	if !config.ShouldNotify(minP, msg.Priority) {
		return
	}
	if msg.ID != 0 && lastID != 0 && msg.ID <= lastID {
		return
	}

	id := strconv.FormatUint(uint64(msg.ID), 10)
	if id == "0" {
		id = fmt.Sprintf("msg-%d", msg.AppID)
	}
	_ = a.notify.Show(id, msg.Title, msg.Message)

	if msg.ID > 0 {
		a.mu.Lock()
		a.cfg.LastMessageID = msg.ID
		cfg := a.cfg
		a.mu.Unlock()
		_ = config.Save(cfg)
	}
}

func (a *App) setError(msg string) {
	a.mu.Lock()
	a.lastErr = msg
	a.mu.Unlock()
}

func (a *App) emitStatus() {
	if a.ctx == nil {
		return
	}
	runtime.EventsEmit(a.ctx, "status", a.GetStatus())
}

func containsUnauthorized(s string) bool {
	return len(s) > 0 && (containsFold(s, "unauthorized") || containsFold(s, "invalid client token"))
}

func containsFold(s, substr string) bool {
	return len(s) >= len(substr) && (s == substr ||
		len(substr) == 0 ||
		(len(s) > 0 && containsFoldIndex(s, substr)))
}

func containsFoldIndex(s, substr string) bool {
	for i := 0; i+len(substr) <= len(s); i++ {
		match := true
		for j := 0; j < len(substr); j++ {
			a, b := s[i+j], substr[j]
			if a >= 'A' && a <= 'Z' {
				a += 'a' - 'A'
			}
			if b >= 'A' && b <= 'Z' {
				b += 'a' - 'A'
			}
			if a != b {
				match = false
				break
			}
		}
		if match {
			return true
		}
	}
	return false
}

