package notify

import (
	"context"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"runtime"
	"sync"

	wailsruntime "github.com/wailsapp/wails/v2/pkg/runtime"
)

// Notifier wraps Wails native notifications with a platform fallback.
type Notifier struct {
	mu      sync.Mutex
	ctx     context.Context
	ready   bool
	initErr error
	lastErr error
	logger  *log.Logger
}

// Init initializes the platform notification system. Call from OnStartup.
func (n *Notifier) Init(ctx context.Context) error {
	n.mu.Lock()
	defer n.mu.Unlock()
	n.ctx = ctx
	n.ensureLogger()

	if err := wailsruntime.InitializeNotifications(ctx); err != nil {
		n.initErr = err
		n.ready = false
		n.logf("wails InitializeNotifications failed: %v (will use platform fallback)", err)
		return err
	}
	if !wailsruntime.IsNotificationAvailable(ctx) {
		n.initErr = fmt.Errorf("notifications not available on this platform")
		n.ready = false
		n.logf("%v (will use platform fallback)", n.initErr)
		return n.initErr
	}
	authorized, err := wailsruntime.CheckNotificationAuthorization(ctx)
	if err == nil && !authorized {
		authorized, err = wailsruntime.RequestNotificationAuthorization(ctx)
		if err != nil || !authorized {
			n.initErr = fmt.Errorf("notification permission denied")
			n.ready = false
			n.logf("%v (will use platform fallback)", n.initErr)
			return n.initErr
		}
	}
	n.ready = true
	n.initErr = nil
	n.logf("wails notifications ready (GOOS=%s)", runtime.GOOS)
	return nil
}

// Ready reports whether the Wails notification backend initialized.
func (n *Notifier) Ready() bool {
	n.mu.Lock()
	defer n.mu.Unlock()
	return n.ready
}

// LastError returns the last notification send/init error, if any.
func (n *Notifier) LastError() string {
	n.mu.Lock()
	defer n.mu.Unlock()
	if n.lastErr != nil {
		return n.lastErr.Error()
	}
	if n.initErr != nil && !n.ready {
		return n.initErr.Error()
	}
	return ""
}

// Show displays a desktop notification.
//
// On Windows, Wails/WinRT often reports success for unpackaged apps without a
// visible toast (missing Start Menu AUMID shortcut). We therefore always use the
// PowerShell AUMID fallback on Windows. On other OSes, try Wails first, then beeep.
func (n *Notifier) Show(id, title, body string) error {
	n.mu.Lock()
	ctx := n.ctx
	ready := n.ready
	n.ensureLogger()
	n.mu.Unlock()

	if title == "" {
		title = "Gotify"
	}

	if runtime.GOOS == "windows" {
		if err := showPlatformToast(title, body); err != nil {
			n.setLastErr(err)
			n.logf("windows toast failed id=%s: %v", id, err)
			return err
		}
		n.setLastErr(nil)
		n.logf("windows toast sent id=%s title=%q", id, title)
		return nil
	}

	var firstErr error
	if ready && ctx != nil {
		err := wailsruntime.SendNotification(ctx, wailsruntime.NotificationOptions{
			ID:    id,
			Title: title,
			Body:  body,
		})
		if err == nil {
			n.setLastErr(nil)
			n.logf("wails notification sent id=%s title=%q", id, title)
			return nil
		}
		firstErr = err
		n.logf("wails SendNotification failed: %v — trying fallback", err)
	}

	if err := showPlatformToast(title, body); err != nil {
		if firstErr != nil {
			err = fmt.Errorf("wails: %v; fallback: %w", firstErr, err)
		}
		n.setLastErr(err)
		n.logf("notification failed: %v", err)
		return err
	}
	n.setLastErr(nil)
	n.logf("fallback notification sent title=%q", title)
	return nil
}

func (n *Notifier) setLastErr(err error) {
	n.mu.Lock()
	n.lastErr = err
	n.mu.Unlock()
}

func (n *Notifier) ensureLogger() {
	if n.logger != nil {
		return
	}
	n.logger = log.New(os.Stderr, "gotify-desktop/notify: ", log.LstdFlags|log.Lmsgprefix)
	dir, err := os.UserConfigDir()
	if err != nil {
		return
	}
	logDir := filepath.Join(dir, "gotify-desktop")
	if err := os.MkdirAll(logDir, 0o700); err != nil {
		return
	}
	f, err := os.OpenFile(filepath.Join(logDir, "notify.log"), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
	if err != nil {
		return
	}
	n.logger = log.New(f, "", log.LstdFlags)
}

func (n *Notifier) logf(format string, args ...any) {
	if n.logger != nil {
		n.logger.Printf(format, args...)
	}
}

import './style.css';
import {Connect, GetStatus, GetClientToken, GetUIPath} from '../wailsjs/go/main/App';
import {EventsOn} from '../wailsjs/runtime/runtime';

const setupView = document.getElementById('setup-view');
const gotifyView = document.getElementById('gotify-view');
const frame = document.getElementById('gotify-frame');
const form = document.getElementById('setup-form');
const errorEl = document.getElementById('error');
const statusLine = document.getElementById('status-line');
const connectBtn = document.getElementById('connect-btn');
const serverInput = document.getElementById('server-url');

/** @type {'setup'|'gotify'|null} */
let currentView = null;

function showError(msg) {
  if (!msg) {
    errorEl.hidden = true;
    errorEl.textContent = '';
    return;
  }
  errorEl.hidden = false;
  errorEl.textContent = msg;
}

function applySession(token) {
  if (!token) return;
  try {
    localStorage.setItem('gotify-login-key', token);
  } catch (_) {
    /* ignore */
  }
  try {
    document.cookie = `gotify-client-token=${encodeURIComponent(token)}; path=/; SameSite=Lax`;
  } catch (_) {
    /* ignore */
  }
}

function showSetup(status) {
  currentView = 'setup';
  setupView.hidden = false;
  gotifyView.hidden = true;
  if (status?.serverUrl) {
    serverInput.value = status.serverUrl;
  }
  frame.src = 'about:blank';
  updateStatusLine(status);
}

async function showGotify(payload, {forceReload = false} = {}) {
  let token = payload?.token;
  let uiPath = payload?.uiPath;
  if (!token) {
    token = await GetClientToken();
  }
  if (!uiPath) {
    uiPath = await GetUIPath();
  }
  applySession(token);

  const alreadyShowing = currentView === 'gotify' && !gotifyView.hidden;
  currentView = 'gotify';
  setupView.hidden = true;
  gotifyView.hidden = false;

  // Do not reload the iframe on every stream status tick — that wiped the Gotify session.
  if (!forceReload && alreadyShowing && frame.src && !frame.src.endsWith('about:blank')) {
    return;
  }
  frame.src = `${uiPath}${uiPath.includes('?') ? '&' : '?'}_=${Date.now()}`;
}

function updateStatusLine(status) {
  if (!status) {
    statusLine.textContent = '';
    return;
  }
  const parts = [];
  if (status.configured) {
    parts.push(status.connected ? 'Stream connected' : 'Stream disconnected');
  } else {
    parts.push('Not configured');
  }
  if (status.notifyReady === false) {
    parts.push('Notify: fallback');
  }
  if (status.notifyError) {
    parts.push('Notify error: ' + status.notifyError);
  }
  if (status.error) {
    parts.push(status.error);
  }
  statusLine.textContent = parts.join(' · ');
}

async function applyStatus(status) {
  if (!status) return;
  if (status.view === 'gotify' && status.configured) {
    // Only mount Gotify once; later status events only refresh the status line.
    await showGotify(null, {forceReload: false});
  } else if (currentView !== 'setup') {
    showSetup(status);
  } else {
    updateStatusLine(status);
    return;
  }
  updateStatusLine(status);
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  showError('');
  connectBtn.disabled = true;
  connectBtn.textContent = 'Connecting…';
  const serverUrl = serverInput.value.trim();
  const username = document.getElementById('username').value;
  const password = document.getElementById('password').value;
  try {
    await Connect(serverUrl, username, password);
    document.getElementById('password').value = '';
    await showGotify(null, {forceReload: true});
  } catch (err) {
    showError(String(err));
  } finally {
    connectBtn.disabled = false;
    connectBtn.textContent = 'Connect';
  }
});

EventsOn('status', (status) => {
  applyStatus(status).catch(console.error);
});
EventsOn('show-setup', () => {
  GetStatus().then(showSetup).catch(console.error);
});
EventsOn('show-gotify', (payload) => {
  showGotify(payload, {forceReload: true}).catch(console.error);
});

GetStatus()
  .then((status) => applyStatus(status))
  .catch((err) => {
    console.error(err);
    showSetup(null);
  });

package gotifyproxy

import (
	"bytes"
	"io"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strconv"
	"strings"
	"sync"
)

const UIPrefix = "/g"

// Proxy reverse-proxies Gotify through the local Wails asset server so the
// embedded UI shares origin with the desktop shell and can stay authenticated
// via the client token (injected as X-Gotify-Key / Cookie).
type Proxy struct {
	mu     sync.RWMutex
	target *url.URL
	token  string
}

// Update sets the upstream Gotify base URL and client token.
func (p *Proxy) Update(serverURL, token string) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if serverURL == "" || token == "" {
		p.target = nil
		p.token = ""
		return nil
	}
	u, err := url.Parse(serverURL)
	if err != nil {
		return err
	}
	p.target = u
	p.token = REDACTED
	return nil
}

// Middleware returns a Wails AssetServer middleware.
func (p *Proxy) Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !p.shouldProxy(r) {
			next.ServeHTTP(w, r)
			return
		}
		p.serve(w, r)
	})
}

func (p *Proxy) shouldProxy(r *http.Request) bool {
	p.mu.RLock()
	ready := p.target != nil && p.token != ""
	p.mu.RUnlock()
	if !ready {
		return false
	}
	path := r.URL.Path
	if path == UIPrefix || strings.HasPrefix(path, UIPrefix+"/") {
		return true
	}
	return isGotifyAPIPath(path)
}

func isGotifyAPIPath(path string) bool {
	prefixes := []string{
		"/current/",
		"/message",
		"/application",
		"/client",
		"/plugin",
		"/stream",
		"/auth/",
		"/health",
		"/version",
		"/image/",
		"/static/",
		"/swagger",
		"/docs",
		"/mcp",
	}
	for _, prefix := range prefixes {
		if path == strings.TrimSuffix(prefix, "/") || strings.HasPrefix(path, prefix) {
			return true
		}
	}
	return false
}

func (p *Proxy) serve(w http.ResponseWriter, r *http.Request) {
	p.mu.RLock()
	target := *p.target
	token := p.token
	p.mu.RUnlock()

	path := r.URL.Path
	uiRequest := path == UIPrefix || strings.HasPrefix(path, UIPrefix+"/")
	if path == UIPrefix {
		path = "/"
	} else if strings.HasPrefix(path, UIPrefix+"/") {
		path = strings.TrimPrefix(path, UIPrefix)
		if path == "" {
			path = "/"
		}
	}

	proxy := httputil.NewSingleHostReverseProxy(&target)
	originalDirector := proxy.Director
	proxy.Director = func(req *http.Request) {
		originalDirector(req)
		req.URL.Scheme = target.Scheme
		req.URL.Host = target.Host
		req.URL.Path = path
		req.Host = target.Host
		req.Header.Set("X-Gotify-Key", token)
		req.Header.Set("Authorization", "Bearer "+token)
		req.Header.Set("Cookie", "gotify-client-token=REDACTED
		req.Header.Del("Origin")
		req.Header.Del("Referer")
	}
	proxy.ModifyResponse = func(resp *http.Response) error {
		resp.Header.Del("X-Frame-Options")
		resp.Header.Del("Content-Security-Policy")
		// Establish a same-origin session cookie for the embedded UI (Gotify v3).
		resp.Header.Add("Set-Cookie", "gotify-client-token="REDACTED"; Path=/; SameSite=Lax")

		if loc := resp.Header.Get("Location"); loc != "" {
			if u, err := url.Parse(loc); err == nil {
				if u.Host == "" || strings.EqualFold(u.Host, target.Host) {
					u.Scheme = ""
					u.Host = ""
					locPath := u.Path
					if locPath == "" || locPath == "/" {
						resp.Header.Set("Location", UIPrefix+"/")
					} else if isGotifyAPIPath(locPath) {
						resp.Header.Set("Location", u.String())
					} else {
						u.Path = UIPrefix + locPath
						resp.Header.Set("Location", u.String())
					}
				}
			}
		}

		if uiRequest && strings.Contains(resp.Header.Get("Content-Type"), "text/html") && resp.Body != nil {
			body, err := io.ReadAll(io.LimitReader(resp.Body, 2<<20))
			_ = resp.Body.Close()
			if err != nil {
				return err
			}
			inject := []byte(`<script>(function(){var t=` + strconv.Quote(token) + `;try{localStorage.setItem('gotify-login-key',t);}catch(e){}try{document.cookie='gotify-client-token='+encodeURIComponent(t)+'; path=/; SameSite=Lax';}catch(e){}})();</script>`)
			if bytes.Contains(body, []byte("<head>")) {
				body = bytes.Replace(body, []byte("<head>"), append([]byte("<head>"), inject...), 1)
			} else {
				body = append(inject, body...)
			}
			resp.Body = io.NopCloser(bytes.NewReader(body))
			resp.Header.Set("Content-Length", strconv.Itoa(len(body)))
			resp.ContentLength = int64(len(body))
		}
		return nil
	}
	proxy.ErrorHandler = func(rw http.ResponseWriter, req *http.Request, err error) {
		http.Error(rw, "gotify proxy error: "+err.Error(), http.StatusBadGateway)
	}
	proxy.ServeHTTP(w, r)
}

