	must(err)
	defer p.Close()
	fmt.Println("local UI:", local)

	client := &http.Client{Timeout: 15 * time.Second}

	// Direct upstream WS
	directWS := strings.Replace(strings.Replace(base, "https://", "wss://", 1), "http://", "ws://", 1) + "/stream?token=" + token
	fmt.Println("=== Direct upstream websocket ===")
	testWS(directWS)

	// Local proxy WS (as Gotify UI does: no query token, cookie/header via proxy)
	localWS := "ws" + strings.TrimPrefix(local, "http") + "/stream"
	fmt.Println("=== Local proxy websocket (no query token) ===")
	testWS(localWS)

	// What Gotify UI under /g/ would open
	fmt.Println("=== Simulate Gotify UI under /g/ (axios then ws path) ===")
	handler := p.Middleware(http.NotFoundHandler())
	rr := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "http://wails.local/g/current/user", nil)
	handler.ServeHTTP(rr, req)
	fmt.Printf("tryAuthenticate -> %d\n", rr.Code)

	// Logout through proxy — DANGEROUS: would delete client. Dry-run by checking we would hit upstream.
	// Instead: POST logout with a COPY would delete — skip destructive call.
	// Verify logout is currently proxied (path match).
	fmt.Printf("isGotifyAPIPath(/auth/logout) via request: ")
	rr = httptest.NewRecorder()
	req = httptest.NewRequest("POST", "http://wails.local/g/auth/logout", nil)
	// Don't actually want to delete — use wrong method through a one-shot check of shouldProxy by GET
	req = httptest.NewRequest("GET", "http://wails.local/auth/logout", nil)
	handler.ServeHTTP(rr, req)
	fmt.Printf("GET /auth/logout through middleware status=%d (proxied if not 404 fallback)\n", rr.Code)

	// Confirm token still valid after our tests
	req, _ = http.NewRequest("GET", base+"/current/user", nil)
	req.Header.Set("X-Gotify-Key", token)
	resp, err := client.Do(req)
	must(err)
	body, _ := io.ReadAll(resp.Body)
	resp.Body.Close()
	fmt.Printf("token still valid upstream: %d %s\n", resp.StatusCode, string(body))
}

func testWS(url string) {
	d := websocket.Dialer{HandshakeTimeout: 10 * time.Second}
	conn, resp, err := d.Dial(url, nil)
	if err != nil {
		status := 0
		if resp != nil {
			status = resp.StatusCode
		}
		fmt.Printf("  FAIL dial %s -> err=%v status=%d\n", url, err, status)
		return
	}
	defer conn.Close()
	_ = conn.SetReadDeadline(time.Now().Add(2 * time.Second))
	_, msg, err := conn.ReadMessage()
	if err != nil {
		fmt.Printf("  OK connected (no message in 2s: %v)\n", err)
		return
	}
	fmt.Printf("  OK connected, message=%s\n", truncate(string(msg), 80))
}

func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "…"
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}
