package autostart

import (
	"fmt"
	"os"
	"path/filepath"
)

const (
	appName     = "Gotify Desktop"
	appID       = "gotify-desktop"
	macosLabel  = "me.elpatron.gotify-desktop"
	windowsName = "GotifyDesktop"
)

// Manager registers the current executable to start at user login.
type Manager struct {
	exe string
}

// New resolves the running executable path for autostart registration.
func New() (*Manager, error) {
	exe, err := os.Executable()
	if err != nil {
		return nil, fmt.Errorf("executable path: %w", err)
	}
	exe, err = filepath.Abs(exe)
	if err != nil {
		return nil, err
	}
	if resolved, err := filepath.EvalSymlinks(exe); err == nil {
		exe = resolved
	}
	return &Manager{exe: exe}, nil
}

// Executable returns the absolute path that would be registered.
func (m *Manager) Executable() string {
	if m == nil {
		return ""
	}
	return m.exe
}

// IsEnabled reports whether login autostart is currently registered.
func (m *Manager) IsEnabled() bool {
	if m == nil {
		return false
	}
	return isEnabled(m.exe)
}

// Enable registers the app to start at login.
func (m *Manager) Enable() error {
	if m == nil {
		return fmt.Errorf("autostart: nil manager")
	}
	return enable(m.exe)
}

// Disable removes the login autostart registration.
func (m *Manager) Disable() error {
	if m == nil {
		return fmt.Errorf("autostart: nil manager")
	}
	return disable()
}

// Set enables or disables autostart.
func (m *Manager) Set(enabled bool) error {
	if enabled {
		return m.Enable()
	}
	return m.Disable()
}

// Toggle flips the current state and returns the new enabled flag.
func (m *Manager) Toggle() (bool, error) {
	if m.IsEnabled() {
		if err := m.Disable(); err != nil {
			return true, err
		}
		return false, nil
	}
	if err := m.Enable(); err != nil {
		return false, err
	}
	return true, nil
}

//go:build linux || freebsd || openbsd || netbsd

package autostart

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func desktopPath() (string, error) {
	dir, err := os.UserConfigDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, "autostart", appID+".desktop"), nil
}

func isEnabled(exe string) bool {
	path, err := desktopPath()
	if err != nil {
		return false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	// Treat as enabled when the file exists and points at our binary (or any Exec).
	s := string(data)
	return strings.Contains(s, "Exec=") && !strings.Contains(s, "Hidden=true")
}

func enable(exe string) error {
	path, err := desktopPath()
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	content := fmt.Sprintf(`[Desktop Entry]
Type=Application
Version=1.0
Name=%s
Comment=Gotify desktop notifications
Exec=%s
Terminal=false
Categories=Network;
X-GNOME-Autostart-enabled=true
`, appName, escapeDesktopExec(exe))
	return os.WriteFile(path, []byte(content), 0o600)
}

func disable() error {
	path, err := desktopPath()
	if err != nil {
		return err
	}
	err = os.Remove(path)
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	return nil
}

// escapeDesktopExec quotes paths with spaces per the Desktop Entry Spec.
func escapeDesktopExec(path string) string {
	if strings.ContainsAny(path, " \t\"'\\$`") {
		r := strings.NewReplacer(`\`, `\\`, `"`, `\"`, `$`, `\$`, "`", "\\`")
		return `"` + r.Replace(path) + `"`
	}
	return path
}

//go:build windows

package autostart

import (
	"strings"

	"golang.org/x/sys/windows/registry"
)

const runKeyPath = `Software\Microsoft\Windows\CurrentVersion\Run`

func isEnabled(exe string) bool {
	k, err := registry.OpenKey(registry.CURRENT_USER, runKeyPath, registry.QUERY_VALUE)
	if err != nil {
		return false
	}
	defer k.Close()
	val, _, err := k.GetStringValue(windowsName)
	if err != nil {
		return false
	}
	return normalizeWinPath(val) != ""
}

func enable(exe string) error {
	k, err := registry.OpenKey(registry.CURRENT_USER, runKeyPath, registry.SET_VALUE)
	if err != nil {
		return err
	}
	defer k.Close()
	return k.SetStringValue(windowsName, quoteWinPath(exe))
}

func disable() error {
	k, err := registry.OpenKey(registry.CURRENT_USER, runKeyPath, registry.SET_VALUE)
	if err != nil {
		return err
	}
	defer k.Close()
	err = k.DeleteValue(windowsName)
	if err == registry.ErrNotExist {
		return nil
	}
	return err
}

func quoteWinPath(path string) string {
	if strings.ContainsAny(path, " \t\"") {
		return `"` + strings.ReplaceAll(path, `"`, `\"`) + `"`
	}
	return path
}

func normalizeWinPath(val string) string {
	return strings.TrimSpace(strings.Trim(val, `"`))
}

